(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const setV = (el, v) => { const d = Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), 'value').set; d.call(el, v); el.dispatchEvent(new Event('input', { bubbles: true })); };
  const cardOf = (text) => [...document.querySelectorAll('.pj-card')].find((c) => (c.innerText || '').includes(text));
  const compCount = () => Number(((cardOf('项目信息')?.innerText || '').replace(/\s+/g, ' ').match(/使用元器件 ([0-9]+) 种/) || [])[1] || -1);
  const out = { online: navigator.onLine };
  const cards = [...document.querySelectorAll('.tb-project-main')];
  (cards.find((c) => (c.innerText || '').includes('温湿度')) || cards[0]).click();
  await sleep(3000);
  out.title = document.querySelector('.pj-title')?.textContent || null;
  out.before = compCount();

  const card = cardOf('项目描述');
  card.querySelector('.pj-link-btn').click();
  await sleep(400);
  setV(card.querySelectorAll('textarea')[0], '断网测试：这条描述是在没有网络的时候写下的。');
  [...card.querySelectorAll('.pj-btn-primary')].find((b) => b.textContent.trim() === '保存').click();
  await sleep(1500);
  out.desc = (cardOf('项目描述')?.innerText || '').replace(/\s+/g, ' ').slice(0, 44);

  const bom = cardOf('元器件清单');
  const addBtn = [...bom.querySelectorAll('.pj-link-btn')].find((b) => b.textContent.includes('添加元件'));
  out.addFormOpened = !!addBtn;
  addBtn.click();
  await sleep(500);
  const inputs = cardOf('元器件清单').querySelectorAll('input');
  out.inputs = inputs.length;
  setV(inputs[0], '断网加的元件');
  setV(inputs[1], '传感器');
  setV(inputs[2], 'DHT11');
  setV(inputs[3], '1');
  const joinBtn = [...cardOf('元器件清单').querySelectorAll('.pj-btn-primary')].find((b) => b.textContent.trim() === '加入作品');
  out.joinBtn = !!joinBtn;
  joinBtn.click();
  await sleep(900);
  out.toastRightAfter = document.querySelector('.pj-toast')?.textContent || null;
  await sleep(1600);
  out.after = compCount();
  const showAll = [...document.querySelectorAll('.pj-link-btn')].find((b) => b.textContent.includes('查看全部'));
  if (showAll) { showAll.click(); await sleep(600); }
  out.bomHasNew = (cardOf('元器件清单')?.innerText || '').includes('断网加的元件');
  return JSON.stringify(out);
})()
